class Node:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.next = None
        self.prev = None

class LinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.memo = {}

    def insert(self, key, value):
        if key in self.memo:
            node = self.memo[key]
            node.value = value
            self.move_to_front(node)
        else:
            node = Node(key, value)
            self.memo[key] = node
            if not self.head:
                self.head = self.tail = node
            else:
                node.next = self.head
                self.head.prev = node
                self.head = node

    def get(self, key):
        if key in self.memo:
            node = self.memo[key]
            self.move_to_front(node)
            return node.value
        return -1

    def move_to_front(self, node):
        if node.prev is None:
            return
        if node.next:
            node.next.prev = node.prev
        else:
            self.tail = node.prev
        node.prev.next = node.next
        node.prev = None
        node.next = self.head
        self.head.prev = node
        self.head = node

def fibonacci(n, mem=None):
    if mem is None:
        mem = LinkedList()
    if n <= 1:
        return n
    cached = mem.get(n)
    if cached != -1:
        return cached
    else:
        fib_value = fibonacci(n-1, mem) + fibonacci(n-2, mem)
        mem.insert(n, fib_value)
        return fib_value

def main():
    n = int(input())
    print(fibonacci(n))

if __name__ == "__main__":
    main()

