import unicodedata

def normalize_and_filter_alpha(s):
    # Normalize Unicode string (NFD separates base chars and diacritics)
    normalized_s = unicodedata.normalize('NFD', s)
    # Keep only base alphabetic chars (ignore diacritics and non-alpha)
    result = []
    for char in normalized_s:
        # Exclude combining marks (Mn)
        if unicodedata.category(char) == 'Mn':
            continue
        if char.isalpha():
            result.append(char.lower())
    return ''.join(result)

def main():
    s = input().rstrip()
    t = input().rstrip()
    s_norm = normalize_and_filter_alpha(s)
    t_norm = normalize_and_filter_alpha(t)
    # Check if s_norm is a subsequence of t_norm
    s_index = 0
    t_index = 0
    while s_index < len(s_norm) and t_index < len(t_norm):
        if s_norm[s_index] == t_norm[t_index]:
            s_index += 1
        t_index += 1
    if s_index == len(s_norm):
        print('True')
    else:
        print('False')

if __name__ == "__main__":
